'use strict';

// MODULES //

var isArray = require( '@stdlib/assert/is-array' );
var isPlainObject = require( '@stdlib/assert/is-plain-object' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var contains = require( '@stdlib/array/base/assert/contains' ).factory;
var format = require( '@stdlib/string/format' );


// VARIABLES //

// Valid operation names per RFC 6902:
var VALID_OPS = [
	'add',
	'remove',
	'replace',
	'move',
	'copy',
	'test'
];

// Operations that require a `value` field:
var VALUE_OPS = [
	'add',
	'replace',
	'test'
];

// Operations that require a `from` field:
var FROM_OPS = [
	'move',
	'copy'
];

var isValidOps = contains( VALID_OPS );
var isValueOps = contains( VALUE_OPS );
var isFromOps = contains( FROM_OPS );


// MAIN //

/**
* Validates the structure of a JSON Patch operations array.
*
* ## Notes
*
* -   Validates per RFC 6902 structural requirements.
* -   Does not validate path semantics (whether paths resolve) — only structure.
* -   Returns `null` if the patch is valid, or an `Error` describing the first validation failure.
*
* @param {Array} operations - JSON Patch operations array
* @returns {(null|Error)} null if valid, or an Error describing the first failure
*
* @example
* var err = validate( [ { 'op': 'add', 'path': '/foo', 'value': 1 } ] );
* // returns null
*
* @example
* var err = validate( 'not an array' );
* // returns <TypeError>
*
* @example
* var err = validate( [ { 'op': 'add', 'path': '/foo' } ] );
* // returns <Error>
*
* @example
* var err = validate( [ { 'op': 'move', 'path': '/foo', 'from': '/bar' } ] );
* // returns null
*/
function validate( operations ) {
	var op;
	var i;

	if ( !isArray( operations ) ) {
		return new TypeError( format( 'invalid argument. Must provide an array. Value: `%s`.', operations ) );
	}
	for ( i = 0; i < operations.length; i++ ) {
		op = operations[ i ];

		// Each operation must be a plain object:
		if ( !isPlainObject( op ) ) {
			return new TypeError( format( 'invalid operation. Operation at index `%d` is not a plain object.', i ) );
		}

		// Must have an `op` field:
		if ( !hasOwnProp( op, 'op' ) || !isString( op.op ) ) {
			return new Error( format( 'invalid operation. Operation at index `%d` is missing a valid `op` field.', i ) );
		}

		// `op` must be one of the six valid operations:
		if ( !isValidOps( op.op ) ) {
			return new Error( format( 'invalid operation. Operation at index `%d` has an unrecognized `op` value: `%s`.', i, op.op ) );
		}

		// Must have a `path` field:
		if ( !hasOwnProp( op, 'path' ) || !isString( op.path ) ) {
			return new Error( format( 'invalid operation. Operation at index `%d` is missing a valid `path` field.', i ) );
		}

		// `add`, `replace`, `test` must have a `value` field (any type allowed):
		if ( isValueOps( op.op ) && !hasOwnProp( op, 'value' ) ) {
			return new Error( format( 'invalid operation. Operation `%s` at index `%d` is missing a `value` field.', op.op, i ) );
		}

		// `move`, `copy` must have a `from` field:
		if ( isFromOps( op.op ) ) {
			if ( !hasOwnProp( op, 'from' ) || !isString( op.from ) ) {
				return new Error( format( 'invalid operation. Operation `%s` at index `%d` is missing a valid `from` field.', op.op, i ) );
			}
		}
	}
	return null;
}


// EXPORTS //

module.exports = validate;
